using System.Security.Cryptography;
using System.Text;
using System.Text.Json;
using DistroNexus.Core.Interfaces;
using DistroNexus.Core.Models;
namespace DistroNexus.Core.Services;
public sealed class ContainerRuntimeService(IEnumerable<IContainerRuntimeAdapter> adapters, ISystemdService systemd, IProcessRunner runner, TimeProvider? timeProvider = null) : IContainerRuntimeService
{
    private const int MaxPreviewGrants = 32; private readonly object _lock = new(); private readonly TimeProvider _time = timeProvider ?? TimeProvider.System; private readonly IReadOnlyList<IContainerRuntimeAdapter> _adapters = adapters.ToArray();
    private readonly Dictionary<string, (PodmanServicePreview P, DateTimeOffset E)> _units = new(); private readonly Dictionary<string, (PodmanConnectionPreview P, DateTimeOffset E, string F, bool Exists)> _connections = new(); private int _reservations;
    public async Task<ContainerRuntimeSnapshot> GetSnapshotAsync(string instanceName, CancellationToken ct = default) { ValidateInstance(instanceName); var rs=new List<ContainerRuntimeStatus>(); var cs=new Dictionary<ContainerRuntimeKind,IReadOnlyList<ContainerSummary>>(); var ims=new Dictionary<ContainerRuntimeKind,IReadOnlyList<ImageSummary>>(); var ps=new Dictionary<ContainerRuntimeKind,IReadOnlyList<ComposeProjectSummary>>(); var fs=new Dictionary<ContainerRuntimeKind,string>(); foreach(var a in _adapters) try { var raw=await a.ProbeAsync(instanceName,ct); var s=raw with { Endpoint = RuntimeEndpointSafety.Normalize(raw.Endpoint) }; rs.Add(s); cs[a.Kind]=s.Availability==ContainerRuntimeAvailability.Unavailable?[]:await a.ListContainersAsync(instanceName,ct); ims[a.Kind]=s.Availability==ContainerRuntimeAvailability.Unavailable?[]:await a.ListImagesAsync(instanceName,ct); ps[a.Kind]=s.Availability==ContainerRuntimeAvailability.Unavailable?[]:await a.ListProjectsAsync(instanceName,ct); } catch(OperationCanceledException) when(ct.IsCancellationRequested){throw;} catch { rs.Add(new(a.Kind,ContainerRuntimeAvailability.Degraded,null,null,"unknown","unknown","Runtime diagnostics failed."));cs[a.Kind]=[];ims[a.Kind]=[];ps[a.Kind]=[];fs[a.Kind]="DN-8101: Runtime diagnostics are unavailable. Review the selected runtime installation and retry.";} return new(rs,cs,ims,ps,fs); }
    public async Task<PodmanServicePreview> PreviewPodmanUserUnitAsync(string name, PodmanUserUnit unit,SystemdAction action,CancellationToken ct=default) { if(action is not(SystemdAction.Start or SystemdAction.Stop))throw new ArgumentException("Only start and stop are permitted for Podman user units."); Reserve(); try {var p=new PodmanServicePreview(await systemd.PreviewAsync(name,Unit(unit),action,SystemdScope.User,ct),unit,action,[new("PodmanUserUnitChange",[action.ToString(),unit.ToString()])],[new("SystemdUserScopeRequired",[])]);lock(_lock){_reservations--;_units[p.SystemdPreview.PreviewToken]=(p,_time.GetUtcNow().AddMinutes(2));}return p;}catch{Release();throw;} }
    public Task<SystemdOperationResult> ExecutePodmanUserUnitAsync(PodmanServicePreview p,CancellationToken ct=default){lock(_lock){Prune();if(!_units.Remove(p.SystemdPreview.PreviewToken,out var g)||g.P!=p)return Task.FromResult(new SystemdOperationResult(false,"PreviewRequired",null,"A current Podman user service/socket preview is required."));}return systemd.ExecuteAsync(p.SystemdPreview,ct);}
    public Task<SystemdOperationResult> ExecutePodmanUserUnitAsync(string token,string name,PodmanUserUnit unit,SystemdAction action,CancellationToken ct=default){lock(_lock){Prune();if(!_units.TryGetValue(token,out var g)||g.P.SystemdPreview.InstanceName!=name||g.P.Unit!=unit||g.P.Action!=action)return Task.FromResult(new SystemdOperationResult(false,"PreviewRequired",null,"A matching current Podman preview is required."));return ExecutePodmanUserUnitAsync(g.P,ct);}}
    public async Task<PodmanConnectionPreview> PreviewPodmanConnectionAsync(string name,PodmanConnectionRequest request,CancellationToken ct=default){ValidateInstance(name);request.Validate();Reserve();try{var probe=await Run(name,["version","--format","{{.Client.Version}}"],ct);if(probe.ExitCode!=0||probe.TimedOut||probe.Failure!=ProcessFailureKind.None)throw new InvalidOperationException("Podman is unavailable; no connection configuration was changed.");var prior=await Inspect(name,request.Name,ct);var exists=prior.ExitCode==0&&!prior.TimedOut&&prior.Failure==ProcessFailureKind.None;var raw=exists?prior.StandardOutput.Trim():"";var safe=SafeEndpoint(raw);var op=exists?"Replace":"Create";var p=new PodmanConnectionPreview(name,request,op,safe,[new("PodmanConnectionChange",[op,request.Name,request.SafeEndpoint])],[new("PodmanReachable",[]),new("NoContainerStorageChange",[])],Guid.NewGuid().ToString("N"));lock(_lock){_reservations--;_connections[p.Token]=(p,_time.GetUtcNow().AddMinutes(2),Fingerprint(raw),exists);}return p;}catch{Release();throw;}}
    public async Task<PodmanConnectionResult> ConfigurePodmanConnectionAsync(PodmanConnectionPreview p,CancellationToken ct=default){p.Request.Validate();(PodmanConnectionPreview P,DateTimeOffset E,string F,bool Exists) g;lock(_lock){Prune();if(!_connections.Remove(p.Token,out g)||g.P!=p)return new(false,"PreviewRequired",Guidance:"Generate and explicitly confirm a current Podman connection preview.");}var current=await Inspect(p.InstanceName,p.Request.Name,ct);var exists=current.ExitCode==0&&!current.TimedOut&&current.Failure==ProcessFailureKind.None; if(exists!=g.Exists||Fingerprint(exists?current.StandardOutput.Trim():"")!=g.F)return new(false,"ConnectionStateDrift",Guidance:"DN-8103: Podman connection configuration changed after preview; generate a new preview.");var add=await Run(p.InstanceName,["system","connection","add","--replace",p.Request.Name,p.Request.SafeEndpoint],ct);if(add.ExitCode!=0||add.TimedOut||add.Failure!=ProcessFailureKind.None)return new(false,add.TimedOut?"TimedOut":"ConnectionConfigureFailed",Guidance:"Podman did not confirm the connection configuration.");var verify=await Inspect(p.InstanceName,p.Request.Name,ct);var endpoint=SafeEndpoint(verify.StandardOutput.Trim());return verify.ExitCode==0&&endpoint==p.Request.SafeEndpoint?new(true,"Succeeded",endpoint):new(false,"PostconditionFailed",Guidance:"Podman did not return the configured endpoint after the change.");}
    public Task<PodmanConnectionResult> ConfigurePodmanConnectionAsync(string token,string name,PodmanConnectionRequest request,CancellationToken ct=default){lock(_lock){Prune();if(!_connections.TryGetValue(token,out var g)||g.P.InstanceName!=name||g.P.Request!=request)return Task.FromResult(new PodmanConnectionResult(false,"PreviewRequired",Guidance:"A matching current Podman preview is required."));return ConfigurePodmanConnectionAsync(g.P,ct);}}
    private void Reserve(){lock(_lock){Prune();if(_units.Count+_connections.Count+_reservations>=MaxPreviewGrants)throw new InvalidOperationException("DN-8102: Too many pending Podman previews; confirm, cancel, or retry shortly.");_reservations++;}} private void Release(){lock(_lock){if(_reservations>0)_reservations--;}} private void Prune(){var now=_time.GetUtcNow();foreach(var k in _units.Where(x=>x.Value.E<now).Select(x=>x.Key).ToArray())_units.Remove(k);foreach(var k in _connections.Where(x=>x.Value.E<now).Select(x=>x.Key).ToArray())_connections.Remove(k);} private Task<ProcessResult> Run(string n,IReadOnlyList<string>a,CancellationToken ct)=>runner.RunAsync(new ProcessRequest("wsl.exe",["--distribution",n,"--exec","podman",..a],TimeSpan.FromSeconds(15),64*1024,64*1024),ct); private Task<ProcessResult> Inspect(string n,string name,CancellationToken ct)=>Run(n,["system","connection","inspect",name,"--format","{{.URI}}"],ct); private static string Fingerprint(string x)=>Convert.ToHexString(SHA256.HashData(Encoding.UTF8.GetBytes(x))); private static void ValidateInstance(string n){if(string.IsNullOrWhiteSpace(n)||n.IndexOfAny(['\r','\n','\0'])>=0)throw new ArgumentException("A valid instance name is required.");} private static SystemdUnitName Unit(PodmanUserUnit u)=>new(u==PodmanUserUnit.Socket?"podman.socket":"podman.service");
    internal static string? SafeEndpoint(string s){if(!Uri.TryCreate(s,UriKind.Absolute,out var u))return null;try{var r=new PodmanConnectionRequest("safe",u);r.Validate();return r.SafeEndpoint;}catch(ArgumentException){return null;}}
}
public sealed class DockerDesktopRuntimeAdapter(IDockerIntegrationService docker, IProcessRunner runner) : IContainerRuntimeAdapter { public ContainerRuntimeKind Kind=>ContainerRuntimeKind.DockerDesktop; public async Task<ContainerRuntimeStatus> ProbeAsync(string n,CancellationToken ct=default){if(!await docker.IsDockerDesktopInstalledAsync(ct))return new(Kind,ContainerRuntimeAvailability.Unavailable,null,null,"unavailable","unavailable","Docker Desktop is not installed.");var s=await docker.GetIntegrationStatusAsync(n,ct);return new(Kind,ContainerRuntimeAvailability.Available,await docker.GetDockerDesktopVersionAsync(ct),null,s.ToString(),s==DockerIntegrationStatus.Enabled?"healthy":"not-integrated","Docker Desktop integration status.");} public async Task<IReadOnlyList<ContainerSummary>> ListContainersAsync(string n,CancellationToken ct=default)=>PodmanWslRuntimeAdapter.ParseContainers((await Run(n,["ps","--all","--format","json"],ct)).StandardOutput); public async Task<IReadOnlyList<ImageSummary>> ListImagesAsync(string n,CancellationToken ct=default)=>PodmanWslRuntimeAdapter.ParseImages((await Run(n,["images","--format","json"],ct)).StandardOutput); public async Task<IReadOnlyList<ComposeProjectSummary>> ListProjectsAsync(string n,CancellationToken ct=default)=>PodmanWslRuntimeAdapter.ParseProjects((await Run(n,["compose","ls","--format","json"],ct)).StandardOutput); private Task<ProcessResult> Run(string n,IReadOnlyList<string>a,CancellationToken ct)=>runner.RunAsync(new ProcessRequest("wsl.exe",["--distribution",n,"--exec","docker",..a],TimeSpan.FromSeconds(15),256*1024,64*1024),ct); }
public sealed class PodmanWslRuntimeAdapter(IProcessRunner runner) : IContainerRuntimeAdapter { public ContainerRuntimeKind Kind=>ContainerRuntimeKind.PodmanWsl; public async Task<ContainerRuntimeStatus> ProbeAsync(string n,CancellationToken ct=default){var v=await Run(n,["version","--format","{{.Client.Version}}"],ct);if(v.ExitCode!=0)return new(Kind,ContainerRuntimeAvailability.Unavailable,null,null,"unavailable","unavailable","Podman is not available in this instance.");var e=await Run(n,["system","connection","list","--format","{{.URI}}"],ct);var socket=await Systemctl(n,"podman.socket",ct);var service=await Systemctl(n,"podman.service",ct);var serviceState=$"socket={State(socket)};service={State(service)}";return new(Kind,e.ExitCode==0?ContainerRuntimeAvailability.Available:ContainerRuntimeAvailability.Degraded,v.StandardOutput.Trim(),e.ExitCode==0?ContainerRuntimeService.SafeEndpoint(e.StandardOutput.Trim()):null,serviceState,e.ExitCode==0?"healthy":"degraded","Podman inside the selected WSL instance.");} public async Task<IReadOnlyList<ContainerSummary>> ListContainersAsync(string n,CancellationToken ct=default)=>ParseContainers((await Run(n,["ps","--all","--format","json"],ct)).StandardOutput); public async Task<IReadOnlyList<ImageSummary>> ListImagesAsync(string n,CancellationToken ct=default)=>ParseImages((await Run(n,["images","--format","json"],ct)).StandardOutput); public async Task<IReadOnlyList<ComposeProjectSummary>> ListProjectsAsync(string n,CancellationToken ct=default)=>ParseProjects((await Run(n,["compose","ls","--format","json"],ct)).StandardOutput); private Task<ProcessResult> Run(string n,IReadOnlyList<string>a,CancellationToken ct)=>runner.RunAsync(new ProcessRequest("wsl.exe",["--distribution",n,"--exec","podman",..a],TimeSpan.FromSeconds(15),256*1024,64*1024),ct); private Task<ProcessResult> Systemctl(string n,string unit,CancellationToken ct)=>runner.RunAsync(new ProcessRequest("wsl.exe",["--distribution",n,"--exec","systemctl","--user","is-active",unit],TimeSpan.FromSeconds(15),4*1024,4*1024),ct); private static string State(ProcessResult result)=>result.ExitCode==0&&result.StandardOutput.Trim().Equals("active",StringComparison.OrdinalIgnoreCase)?"active":result.StandardOutput.Trim().Equals("inactive",StringComparison.OrdinalIgnoreCase)?"inactive":"unknown"; public static IReadOnlyList<ContainerSummary> ParseContainers(string j)=>Parse(j,e=>new ContainerSummary(Value(e,"Id","ID"),Value(e,"Names","Name"),Value(e,"Image"),Value(e,"State","Status"),Value(e,"Ports"))); public static IReadOnlyList<ImageSummary> ParseImages(string j)=>Parse(j,e=>new ImageSummary(Value(e,"Id","ID"),Value(e,"Repository","RepositoryName"),Value(e,"Tag"),Value(e,"Size"))); public static IReadOnlyList<ComposeProjectSummary> ParseProjects(string j)=>Parse(j,e=>new ComposeProjectSummary(Value(e,"Name"),Value(e,"Status"),int.TryParse(Value(e,"Services"),out var x)?x:0)); private static IReadOnlyList<T> Parse<T>(string j,Func<JsonElement,T>m){try{if(!j.TrimStart().StartsWith('['))j="["+string.Join(',',j.Split('\n',StringSplitOptions.RemoveEmptyEntries|StringSplitOptions.TrimEntries))+"]";using var d=JsonDocument.Parse(j);return d.RootElement.ValueKind!=JsonValueKind.Array?[]:d.RootElement.EnumerateArray().Where(x=>x.ValueKind==JsonValueKind.Object).Select(m).ToArray();}catch{return[];}} private static string Value(JsonElement e,params string[] ns)=>ns.FirstOrDefault(n=>e.TryGetProperty(n,out var p)&&p.ValueKind==JsonValueKind.String) is { } n&&e.TryGetProperty(n,out var v)?v.GetString()??"":""; }
public sealed class PodmanDesktopRuntimeAdapter : IContainerRuntimeAdapter { private readonly IProcessRunner _runner; private readonly Func<bool> _isInstalled; public PodmanDesktopRuntimeAdapter(IProcessRunner runner) : this(runner, new WindowsPodmanDesktopInstallationDetector()) { } public PodmanDesktopRuntimeAdapter(IProcessRunner runner, IPodmanDesktopInstallationDetector detector) : this(runner, detector.IsInstalled) { } public PodmanDesktopRuntimeAdapter(IProcessRunner runner, Func<bool> installed) => (_runner, _isInstalled) = (runner, installed); public ContainerRuntimeKind Kind=>ContainerRuntimeKind.PodmanDesktop; public async Task<ContainerRuntimeStatus> ProbeAsync(string n,CancellationToken ct=default){if(!_isInstalled())return new(Kind,ContainerRuntimeAvailability.Unavailable,null,null,"unavailable","unavailable","Podman Desktop is not installed on Windows.");var v=await Run(["version","--format","{{.Client.Version}}"],ct);if(v.ExitCode!=0)return new(Kind,ContainerRuntimeAvailability.Unavailable,null,null,"unavailable","unavailable","Podman Desktop is installed but unavailable on Windows.");var e=await Run(["system","connection","list","--format","{{.URI}}"],ct);return new(Kind,e.ExitCode==0?ContainerRuntimeAvailability.Available:ContainerRuntimeAvailability.Degraded,SafeVersion(v.StandardOutput),e.ExitCode==0?ContainerRuntimeService.SafeEndpoint(e.StandardOutput.Trim()):null,"unknown",e.ExitCode==0?"healthy":"degraded","Podman Desktop on Windows.");} public async Task<IReadOnlyList<ContainerSummary>> ListContainersAsync(string n,CancellationToken ct=default)=>PodmanWslRuntimeAdapter.ParseContainers((await Run(["ps","--all","--format","json"],ct)).StandardOutput); public async Task<IReadOnlyList<ImageSummary>> ListImagesAsync(string n,CancellationToken ct=default)=>PodmanWslRuntimeAdapter.ParseImages((await Run(["images","--format","json"],ct)).StandardOutput); public async Task<IReadOnlyList<ComposeProjectSummary>> ListProjectsAsync(string n,CancellationToken ct=default)=>PodmanWslRuntimeAdapter.ParseProjects((await Run(["compose","ls","--format","json"],ct)).StandardOutput); private Task<ProcessResult> Run(IReadOnlyList<string>a,CancellationToken ct)=>_runner.RunAsync(new ProcessRequest("podman.exe",a,TimeSpan.FromSeconds(15),256*1024,64*1024),ct); private static string? SafeVersion(string value)=>VersionSafety.Normalize(value); }
